import SwiftUI

@main
struct HostApp: App {
    var body: some Scene {
        WindowGroup { Text("host") }
    }
}

import XCTest

final class TapTests: XCTestCase {
    func testOpenPhoenixRoom() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()

        let phoenix = app.staticTexts["Project Phoenix"].firstMatch
        XCTAssertTrue(phoenix.waitForExistence(timeout: 30), "home screen not found")
        phoenix.tap()

        Thread.sleep(forTimeInterval: 4)
        let dump1 = app.debugDescription
        try? dump1.write(toFile: "/tmp/element_hierarchy_room.txt", atomically: true, encoding: .utf8)

        var tapped = false
        let labels = ["...", "Room options", "Options", "Menu", "Room settings", "Settings"]
        for l in labels {
            let b = app.buttons[l]
            if b.waitForExistence(timeout: 2) {
                b.tap()
                tapped = true
                break
            }
        }
        if !tapped {
            let navButtons = app.navigationBars.firstMatch.buttons
            if navButtons.count > 0 {
                navButtons.allElementsBoundByIndex.last?.tap()
                tapped = true
            }
        }
        XCTAssertTrue(tapped, "could not find options button")

        Thread.sleep(forTimeInterval: 3)
        let dump2 = app.debugDescription
        try? dump2.write(toFile: "/tmp/element_hierarchy_menu.txt", atomically: true, encoding: .utf8)
    }
}

import XCTest

final class TapTests: XCTestCase {
    func dump(_ app: XCUIApplication, _ name: String) {
        let d = app.debugDescription
        let path = NSHomeDirectory() + "/" + name
        try? d.write(toFile: path, atomically: true, encoding: .utf8)
        NSLog("DUMP_WRITTEN \(path)")
    }

    func dismissAlert(_ app: XCUIApplication) {
        for label in ["Got it", "OK", "Close", "Dismiss"] {
            let b = app.buttons[label]
            if b.waitForExistence(timeout: 2) {
                b.tap()
                Thread.sleep(forTimeInterval: 1)
                return
            }
        }
    }

    func testOpenPhoenixRoom() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()
        dismissAlert(app)

        let phoenix = app.staticTexts["Project Phoenix"].firstMatch
        XCTAssertTrue(phoenix.waitForExistence(timeout: 30), "home screen not found")
        phoenix.tap()
        Thread.sleep(forTimeInterval: 3)
        dismissAlert(app)
        Thread.sleep(forTimeInterval: 2)

        dump(app, "hier_room.txt")

        var tapped = false
        let all = app.buttons.allElementsBoundByIndex
        for b in all {
            let label = b.label.lowercased()
            let ident = b.identifier.lowercased()
            if label.contains("...") || label.contains("option") || label.contains("more")
                || ident.contains("option") || ident.contains("more") || ident.contains("settings")
                || ident.contains("...") {
                NSLog("TAP_CANDIDATE label=\(b.label) ident=\(b.identifier)")
                if b.isHittable {
                    b.tap()
                    tapped = true
                    break
                }
            }
        }
        NSLog("TAPPED=\(tapped)")
        Thread.sleep(forTimeInterval: 3)
        dump(app, "hier_menu.txt")
    }
}

